// Desenho em colunas: cada servico fica na coluna da sua profundidade na cadeia de chamadas
// (user, api, orquestrador, bancos e provedores), e a ordem dentro da coluna evita cruzamentos.
const dark = !(context.grafana && context.grafana.theme && context.grafana.theme.isLight);
const C = dark
  ? { text: '#d8d9da', muted: '#8e9bae', box: '#1b1f27', bg: '#111217', line: '#556070', edge: '#6b7788' }
  : { text: '#24292e', muted: '#6b7785', box: '#ffffff', bg: '#f7f8fa', line: '#b8c2cc', edge: '#8a97a6' };
const GREEN = '#73bf69', ORANGE = '#ff9830', RED = '#f2495c', GRAY = '#8e8e8e';
const health = (f) => (f == null || isNaN(f) ? GRAY : f >= 0.05 ? RED : f > 0.0001 ? ORANGE : GREEN);

const A = {}, B = {}, L = {};
for (const s of context.panel.data.series) {
  const v = s.fields.find((f) => f.type === 'number');
  if (!v || !v.labels || !v.labels.client || !v.labels.server) continue;
  const val = v.values[v.values.length - 1];
  if (val == null || isNaN(val)) continue;
  (s.refId === 'B' ? B : s.refId === 'C' ? L : A)[v.labels.client + '>' + v.labels.server] = val;
}

const edges = Object.keys(A)
  .filter((k) => A[k] > 0 && k.split('>')[0] !== k.split('>')[1])
  .map((k) => {
    const [s, t] = k.split('>');
    return { k, s, t, v: A[k], f: Math.min(1, (B[k] || 0) / A[k]), lat: L[k] };
  });
const names = [...new Set(edges.flatMap((e) => [e.s, e.t]))];

// Profundidade: o caminho mais longo ate o servico (limitado, por causa de ciclos).
const depth = {};
names.forEach((n) => (depth[n] = 0));
for (let i = 0; i < names.length; i++) {
  let changed = false;
  for (const e of edges) {
    if (depth[e.t] < depth[e.s] + 1 && depth[e.s] + 1 < names.length) {
      depth[e.t] = depth[e.s] + 1;
      changed = true;
    }
  }
  if (!changed) break;
}
// Quem nao chama ninguem (bancos, provedores, servicos-folha) vai para a ultima coluna.
const callers = new Set(edges.map((e) => e.s));
const lastInner = Math.max(0, ...names.filter((n) => callers.has(n)).map((n) => depth[n]));
names.forEach((n) => { if (!callers.has(n)) depth[n] = lastInner + 1; });
const cols = [];
names.forEach((n) => (cols[depth[n]] = cols[depth[n]] || []).push(n));
for (let i = 0; i < cols.length; i++) cols[i] = cols[i] || [];
const STORES = ['mysql', 'redis', 'qdrant'];
const prio = (n) => (STORES.includes(n) ? 2 : n.includes('.') ? 1 : 0);
cols.forEach((c) => c.sort((a, b) => prio(a) - prio(b) || a.localeCompare(b)));
const rank = {};
const setRank = () => cols.forEach((c) => c.forEach((n, i) => (rank[n] = (i + 0.5) / c.length)));
setRank();
for (let pass = 0; pass < 3; pass++) {
  cols.forEach((c, d) => {
    if (d === 0) return;
    const bary = (n) => {
      const ps = edges.filter((e) => e.t === n && depth[e.s] < d).map((e) => rank[e.s]);
      return ps.length ? ps.reduce((a, b) => a + b, 0) / ps.length : rank[n];
    };
    const b = {};
    c.forEach((n) => (b[n] = bary(n)));
    c.sort((x, y) => b[x] - b[y] || prio(x) - prio(y) || x.localeCompare(y));
  });
  setRank();
}
const maxCount = Math.max(1, ...cols.map((c) => c.length));
const X = {}, Y = {};
cols.forEach((c, d) =>
  c.forEach((n, i) => {
    X[n] = ((d + 0.5) / cols.length) * 1000;
    Y[n] = 500 + (i - (c.length - 1) / 2) * (1000 / maxCount);
  }));

const short = (n) => (n.length > 24 ? n.slice(0, 23) + '…' : n);
const fmtInt = (n) => (n >= 10000 ? (n / 1000).toFixed(1) + ' mil' : String(Math.round(n)));
const fmtLat = (s) => (s == null || isNaN(s) ? '' : s < 1 ? Math.round(s * 1000) + ' ms' : s.toFixed(1) + ' s');

// Curva em S (tangentes horizontais) entre dois centros, em qualquer espaco de coordenadas.
const bez = (p0, p3, t) => {
  const mx = (p0[0] + p3[0]) / 2, u = 1 - t;
  const w = [u * u * u, 3 * u * u * t, 3 * u * t * t, t * t * t];
  return [w[0] * p0[0] + w[1] * mx + w[2] * mx + w[3] * p3[0], w[0] * p0[1] + w[1] * p0[1] + w[2] * p3[1] + w[3] * p3[1]];
};

// Seta e rotulo de cada ligacao: a curva sai da borda do cartao de origem e chega a borda do de destino.
const edgeSeries = (NW, NH, width, color, label, tip) => ({
  type: 'custom',
  coordinateSystem: 'cartesian2d',
  zlevel: 0,
  z: 2,
  encode: { x: [0, 2], y: [1, 3] },
  data: edges.map((e, i) => [X[e.s], Y[e.s], X[e.t], Y[e.t], i]),
  tooltip: { formatter: (p) => tip(edges[p.dataIndex]) },
  renderItem: (params, api) => {
    const e = edges[api.value(4)];
    const p1 = api.coord([api.value(0), api.value(1)]);
    const p2 = api.coord([api.value(2), api.value(3)]);
    const inside = (p, c) => Math.abs(p[0] - c[0]) < NW / 2 + 3 && Math.abs(p[1] - c[1]) < NH / 2 + 3;
    const pts = [];
    for (let i = 0; i <= 60; i++) {
      const p = bez(p1, p2, i / 60);
      if (!inside(p, p1) && !inside(p, p2)) pts.push(p);
    }
    if (pts.length < 3) return null;
    const last = pts[pts.length - 1], prev = pts[pts.length - 3];
    const ang = Math.atan2(last[1] - prev[1], last[0] - prev[0]), col = color(e), w = width(e);
    const head = [
      last,
      [last[0] - 10 * Math.cos(ang - 0.4), last[1] - 10 * Math.sin(ang - 0.4)],
      [last[0] - 10 * Math.cos(ang + 0.4), last[1] - 10 * Math.sin(ang + 0.4)],
    ];
    const txt = label(e), pw = txt.length * 6.4 + 12;
    // Perto do destino: la as curvas ja estao separadas, no meio elas se amontoam.
    const m = pts[Math.floor((pts.length - 1) * 0.72)];
    return {
      type: 'group',
      children: [
        { type: 'polyline', shape: { points: pts }, style: { stroke: col, lineWidth: w, opacity: 0.6, fill: 'none' } },
        { type: 'polygon', shape: { points: head }, style: { fill: col, opacity: 0.9 } },
        { type: 'rect', shape: { x: m[0] - pw / 2, y: m[1] - 9, width: pw, height: 18, r: 9 }, style: { fill: C.bg, stroke: C.line, lineWidth: 1 } },
        { type: 'text', style: { text: txt, x: m[0], y: m[1], textAlign: 'center', textVerticalAlign: 'middle', fill: C.text, font: '11px sans-serif' } },
      ],
    };
  },
});

// Cartoes dos servicos, desenhados acima das setas.
const nodeSeries = (NW, NH, border, line2) => ({
  type: 'custom',
  coordinateSystem: 'cartesian2d',
  zlevel: 1,
  z: 5,
  encode: { x: 0, y: 1 },
  data: names.map((n) => [X[n], Y[n], n]),
  tooltip: { show: false },
  renderItem: (params, api) => {
    const n = api.value(2), p = api.coord([api.value(0), api.value(1)]);
    const sub = line2(n);
    return {
      type: 'group',
      children: [
        { type: 'rect', shape: { x: p[0] - NW / 2, y: p[1] - NH / 2, width: NW, height: NH, r: 8 }, style: { fill: C.box, stroke: border(n), lineWidth: 2 } },
        { type: 'text', style: { text: short(n), x: p[0], y: p[1] - (sub ? 8 : 0), textAlign: 'center', textVerticalAlign: 'middle', fill: C.text, font: '600 12px sans-serif' } },
        ...(sub ? [{ type: 'text', style: { text: sub, x: p[0], y: p[1] + 9, textAlign: 'center', textVerticalAlign: 'middle', fill: C.muted, font: '10px sans-serif' } }] : []),
      ],
    };
  },
});

const base = {
  animation: false,
  grid: { left: 16, right: 16, top: 16, bottom: 16 },
  xAxis: { type: 'value', min: 0, max: 1000, show: false },
  yAxis: { type: 'value', min: 0, max: 1000, inverse: true, show: false },
  tooltip: { trigger: 'item', confine: true },
};
if (!edges.length) {
  base.graphic = [{ type: 'text', left: 'center', top: 'middle', style: { text: 'ainda sem chamadas entre serviços', fill: C.muted, font: '13px sans-serif' } }];
}
// Mapa de servicos: totais do periodo. A: chamadas; B: falhas; C: latencia media (s) por ligacao.
const NW = 176, NH = 42;
const inOf = (n) => edges.filter((e) => e.t === n);
const inCount = (n) => inOf(n).reduce((a, e) => a + e.v, 0);
const inFail = (n) => inOf(n).reduce((a, e) => a + e.v * e.f, 0);
const lat = (n) => {
  const es = inOf(n).filter((e) => e.lat != null && !isNaN(e.lat));
  const w = es.reduce((a, e) => a + e.v, 0);
  return w ? es.reduce((a, e) => a + e.lat * e.v, 0) / w : null;
};
const maxV = Math.max(1, ...edges.map((e) => e.v));
const nodeFail = (n) => (inCount(n) ? inFail(n) / inCount(n) : null);
const line2 = (n) => {
  const c = inCount(n) || edges.filter((e) => e.s === n).reduce((a, e) => a + e.v, 0);
  if (!c) return '';
  const f = nodeFail(n);
  return [fmtInt(c) + ' chamadas', fmtLat(lat(n)), f ? (f * 100).toFixed(1) + '% falha' : ''].filter(Boolean).join(' · ');
};
return {
  ...base,
  series: [
    edgeSeries(
      NW, NH,
      (e) => 1 + 5 * Math.sqrt(e.v / maxV),
      (e) => (e.f >= 0.05 ? RED : e.f > 0.0001 ? ORANGE : C.edge),
      (e) => fmtInt(e.v),
      (e) => e.s + ' → ' + e.t + '<br/>' + Math.round(e.v) + ' chamadas<br/>falhas: ' + (e.f * 100).toFixed(1) + '%' +
        (e.lat != null ? '<br/>latência média: ' + fmtLat(e.lat) : '')),
    nodeSeries(NW, NH, (n) => (inCount(n) ? health(nodeFail(n)) : C.line), line2),
  ],
};

