// Fluxo ao vivo: A: chamadas/s por ligacao; B: falhas/s por ligacao (ausente quando nao ha falha).
const NW = 150, NH = 30;
const maxV = Math.max(0.01, ...edges.map((e) => e.v));
const rate = (r) => (r >= 1 ? r.toFixed(1) : r.toFixed(2)) + '/s';
